Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
gfs2: fix memory leaks in gfs2_fill_super error path

Fix two memory leaks in the gfs2_fill_super() error handling path when
transitioning a filesystem to read-write mode fails.

First leak: kthread objects (thread_struct, task_struct, etc.)
When gfs2_freeze_lock_shared() fails after init_threads() succeeds, the
created kernel threads (logd and quotad) are never destroyed. This
occurs because the fail_per_node label doesn't call
gfs2_destroy_threads().

Second leak: quota bitmap buffer (8192 bytes)
When gfs2_make_fs_rw() fails after gfs2_quota_init() succeeds but
before other operations complete, the allocated quota bitmap is never
freed.

The fix moves thread cleanup to the fail_per_node label to handle all
error paths uniformly. gfs2_destroy_threads() is safe to call
unconditionally as it checks for NULL pointers. Quota cleanup is added
in gfs2_make_fs_rw() to properly handle the withdrawal case where
quota initialization succeeds but the filesystem is then withdrawn.

Thread leak backtrace (gfs2_freeze_lock_shared failure):
  unreferenced object 0xffff88801d7bca80 (size 4480):
    copy_process+0x3a1/0x4670 kernel/fork.c:2422
    kernel_clone+0xf3/0x6e0 kernel/fork.c:2779
    kthread_create_on_node+0x100/0x150 kernel/kthread.c:478
    init_threads+0xab/0x350 fs/gfs2/ops_fstype.c:611
    gfs2_fill_super+0xe5c/0x1240 fs/gfs2/ops_fstype.c:1265

Quota leak backtrace (gfs2_make_fs_rw failure):
  unreferenced object 0xffff88812de7c000 (size 8192):
    gfs2_quota_init+0xe5/0x820 fs/gfs2/quota.c:1409
    gfs2_make_fs_rw+0x7a/0xe0 fs/gfs2/super.c:149
    gfs2_fill_super+0xfbb/0x1240 fs/gfs2/ops_fstype.c:1275

Reported-by: syzbot+aac438d7a1c44071e04b@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=aac438d7a1c44071e04b
Fixes: 6c7410f44961 ("gfs2: gfs2_freeze_lock_shared cleanup")
Fixes: b66f723bb552 ("gfs2: Improve gfs2_make_fs_rw error handling")
Link: https://lore.kernel.org/all/20260131062509.77974-1-kartikey406@gmail.com/T/ [v1]
Signed-off-by: Deepanshu Kartikey <kartikey406@gmail.com>
Signed-off-by: Andreas Gruenbacher <agruenba@redhat.com>

Here is the root cause:
In the error handling path of gfs2_fill_super, when gfs2_freeze_lock_shared() fails after init_threads() succeeds, kernel threads (logd, quotad) are not destroyed because gfs2_destroy_threads() was incorrectly placed only inside the gfs2_make_fs_rw error block, not at the fail_per_node label. Additionally, in gfs2_make_fs_rw, if gfs2_quota_init() succeeds but the filesystem is withdrawn, the allocated quota bitmap buffer is not freed because gfs2_quota_cleanup() is missing.

Here is the patch:
  */
 static int gfs2_fill_super(struct super_block *sb, struct fs_context *fc)
 {
 	struct gfs2_args *args = fc->fs_private;
 	int silent = fc->sb_flags & SB_SILENT;
 	struct gfs2_sbd *sdp;
 	struct gfs2_holder mount_gh;
 	struct address_space *mapping;
 	int error;

 	sdp = init_sbd(sb);
 	if (!sdp) {
 		pr_warn("can't alloc struct gfs2_sbd\n");
 		return -ENOMEM;
 	}
 	sdp->sd_args = *args;

 	if (sdp->sd_args.ar_spectator) {
                 sb->s_flags |= SB_RDONLY;
 		set_bit(SDF_RORECOVERY, &sdp->sd_flags);
 	}
 	if (sdp->sd_args.ar_posix_acl)
 		sb->s_flags |= SB_POSIXACL;
 	if (sdp->sd_args.ar_nobarrier)
 		set_bit(SDF_NOBARRIERS, &sdp->sd_flags);

 	sb->s_flags |= SB_NOSEC;
 	sb->s_magic = GFS2_MAGIC;
 	sb->s_op = &gfs2_super_ops;

 	set_default_d_op(sb, &gfs2_dops);
 	sb->s_export_op = &gfs2_export_ops;
 	sb->s_qcop = &gfs2_quotactl_ops;
 	sb->s_quota_types = QTYPE_MASK_USR | QTYPE_MASK_GRP;
 	sb_dqopt(sb)->flags |= DQUOT_QUOTA_SYS_FILE;
 	sb->s_time_gran = 1;
 	sb->s_maxbytes = MAX_LFS_FILESIZE;

 	/* Set up the buffer cache and fill in some fake block size values
 	   to allow us to read-in the on-disk superblock. */
 	sdp->sd_sb.sb_bsize = sb_min_blocksize(sb, SECTOR_SIZE);
 	error = -EINVAL;
 	if (!sdp->sd_sb.sb_bsize)
 		goto fail_free;
 	sdp->sd_sb.sb_bsize_shift = sb->s_blocksize_bits;
 	sdp->sd_fsb2bb_shift = sdp->sd_sb.sb_bsize_shift - SECTOR_SHIFT;
 	sdp->sd_fsb2bb = BIT(sdp->sd_fsb2bb_shift);

 	sdp->sd_tune.gt_logd_secs = sdp->sd_args.ar_commit;
 	sdp->sd_tune.gt_quota_quantum = sdp->sd_args.ar_quota_quantum;
 	if (sdp->sd_args.ar_statfs_quantum) {
 		sdp->sd_tune.gt_statfs_slow = 0;
 		sdp->sd_tune.gt_statfs_quantum = sdp->sd_args.ar_statfs_quantum;
 	} else {
 		sdp->sd_tune.gt_statfs_slow = 1;
 		sdp->sd_tune.gt_statfs_quantum = 30;
 	}

 	/* Set up an address space for metadata writes */
 	sdp->sd_inode = new_inode(sb);
 	error = -ENOMEM;
 	if (!sdp->sd_inode)
 		goto fail_free;
 	sdp->sd_inode->i_ino = GFS2_BAD_INO;
 	sdp->sd_inode->i_size = OFFSET_MAX;

 	mapping = gfs2_aspace(sdp);
 	mapping->a_ops = &gfs2_rgrp_aops;
 	gfs2_setup_inode(sdp->sd_inode);

 	error = init_names(sdp, silent);
 	if (error)
 		goto fail_iput;

 	snprintf(sdp->sd_fsname, sizeof(sdp->sd_fsname), "%s", sdp->sd_table_name);

 	error = -ENOMEM;
 	sdp->sd_glock_wq = alloc_workqueue("gfs2-glock/%s",
 			WQ_MEM_RECLAIM | WQ_HIGHPRI | WQ_FREEZABLE | WQ_PERCPU,
 			0,
 			sdp->sd_fsname);
 	if (!sdp->sd_glock_wq)
 		goto fail_iput;

 	sdp->sd_delete_wq = alloc_workqueue("gfs2-delete/%s",
 			WQ_MEM_RECLAIM | WQ_FREEZABLE | WQ_PERCPU, 0,
 			sdp->sd_fsname);
 	if (!sdp->sd_delete_wq)
 		goto fail_glock_wq;

 	error = gfs2_sys_fs_add(sdp);
 	if (error)
 		goto fail_delete_wq;

 	gfs2_create_debugfs_file(sdp);

 	error = gfs2_lm_mount(sdp, silent);
 	if (error)
 		goto fail_debug;

 	INIT_WORK(&sdp->sd_withdraw_work, gfs2_withdraw_func);

 	error = init_locking(sdp, &mount_gh, DO);
 	if (error)
 		goto fail_lm;

 	error = init_sb(sdp, silent);
 	if (error)
 		goto fail_locking;

 	/* Turn rgrplvb on by default if fs format is recent enough */
 	if (!sdp->sd_args.ar_got_rgrplvb && sdp->sd_sb.sb_fs_format > 1801)
 		sdp->sd_args.ar_rgrplvb = 1;

 	error = wait_on_journal(sdp);
 	if (error)
 		goto fail_sb;

 	/*
 	 * If user space has failed to join the cluster or some similar
 	 * failure has occurred, then the journal id will contain a
 	 * negative (error) number. This will then be returned to the
 	 * caller (of the mount syscall). We do this even for spectator
 	 * mounts (which just write a jid of 0 to indicate "ok" even though
 	 * the jid is unused in the spectator case)
 	 */
 	if (sdp->sd_lockstruct.ls_jid < 0) {
 		error = sdp->sd_lockstruct.ls_jid;
 		sdp->sd_lockstruct.ls_jid = 0;
 		goto fail_sb;
 	}

 	if (sdp->sd_args.ar_spectator)
 		snprintf(sdp->sd_fsname, sizeof(sdp->sd_fsname), "%s.s",
 			 sdp->sd_table_name);
 	else
 		snprintf(sdp->sd_fsname, sizeof(sdp->sd_fsname), "%s.%u",
 			 sdp->sd_table_name, sdp->sd_lockstruct.ls_jid);

 	error = init_inodes(sdp, DO);
 	if (error)
 		goto fail_sb;

 	error = init_per_node(sdp, DO);
 	if (error)
 		goto fail_inodes;

 	error = gfs2_statfs_init(sdp);
 	if (error) {
 		fs_err(sdp, "can't initialize statfs subsystem: %d\n", error);
 		goto fail_per_node;
 	}

 	if (!sb_rdonly(sb)) {
 		error = init_threads(sdp);
 		if (error)
 			goto fail_per_node;
 	}

 	error = gfs2_freeze_lock_shared(sdp);
 	if (error)
 		goto fail_per_node;

 	if (!sb_rdonly(sb))
 		error = gfs2_make_fs_rw(sdp);

 	if (error) {
 		gfs2_freeze_unlock(sdp);
-		gfs2_destroy_threads(sdp);
 		fs_err(sdp, "can't make FS RW: %d\n", error);
 		goto fail_per_node;
 	}
 	gfs2_glock_dq_uninit(&mount_gh);
 	gfs2_online_uevent(sdp);
 	return 0;

 fail_per_node:
 	init_per_node(sdp, UNDO);
+	gfs2_destroy_threads(sdp);
 fail_inodes:
 	init_inodes(sdp, UNDO);
 fail_sb:
 	if (sdp->sd_root_dir)
 		dput(sdp->sd_root_dir);
 	if (sdp->sd_master_dir)
 		dput(sdp->sd_master_dir);
 	if (sb->s_root)
 		dput(sb->s_root);
 	sb->s_root = NULL;
 fail_locking:
 	init_locking(sdp, &mount_gh, UNDO);
 fail_lm:
 	complete_all(&sdp->sd_journal_ready);
 	gfs2_gl_hash_clear(sdp);
 	gfs2_lm_unmount(sdp);
 fail_debug:
 	gfs2_delete_debugfs_file(sdp);
 	gfs2_sys_fs_del(sdp);
 fail_delete_wq:
 	destroy_workqueue(sdp->sd_delete_wq);
 fail_glock_wq:
 	if (sdp->sd_glock_wq)
 		destroy_workqueue(sdp->sd_glock_wq);
 fail_iput:
 	iput(sdp->sd_inode);
 fail_free:
 	free_sbd(sdp);
 	return error;
 }



